INSERT INTO `wp_w4n296_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(319, 1, '2024-10-25 15:39:36', '2024-10-25 15:39:36', '<h2>Be a Catalyst for Change</h2>		\n		<p>Your involvement can transform lives. Join us in empowering women and girls across Tanzania.</p>		\n			<h2>Why Involvement<br> Matters</h2>		\n		<p>Fursa Foundation is a community-based organization founded by young medical doctors in Mwanza, Tanzania, We are dedicated to empowering adolescents, young women, and underserved communities through initiatives that promote menstrual hygiene, women’s entrepreneurship, and gender equality.</p>		\n			<svg xmlns=\"http://www.w3.org/2000/svg\" xmlns:xlink=\"http://www.w3.org/1999/xlink\" width=\"512\" height=\"512\" viewBox=\"0 0 512 512\" fill=\"none\"><mask id=\"mask0_118_59\" style=\"mask-type:alpha\" maskUnits=\"userSpaceOnUse\" x=\"0\" y=\"0\" width=\"512\" height=\"512\"><rect width=\"512\" height=\"512\" fill=\"url(#pattern0_118_59)\"></rect></mask><g mask=\"url(#mask0_118_59)\"><rect x=\"-32\" y=\"-32\" width=\"544\" height=\"544\" fill=\"#005CA9\"></rect></g><defs><pattern id=\"pattern0_118_59\" patternContentUnits=\"objectBoundingBox\" width=\"1\" height=\"1\"><use xlink:href=\"#image0_118_59\" transform=\"scale(0.00195312)\"></use></pattern><image id=\"image0_118_59\" width=\"512\" height=\"512\" xlink:href=\"data:image/png;base64,\"></image></defs></svg>			\n			<h5>Your Support Makes a Difference</h5>		\n		<p>Your contribution provides reusable sanitary pads, entrepreneurship training, and vital support for survivors of gender-based violence.</p>		\n									<button data-toggle=\"premium-modal\" data-target=\"#premium-modal-2a34480\" type=\"button\" data-text=\"Donate Today\">\n							Donate Today\n					</button>\n															<h3>\n									How to Donate								</h3>\n									<button type=\"button\" data-dismiss=\"premium-modal\">&times;</button>\n						<p>Your support helps us continue empowering women and girls in Tanzania. To make a direct donation, please follow the instructions below:</p><p> </p><hr /><p> </p><p><strong>Bank Transfer Instructions</strong>:</p><ul><li><strong>Bank Name</strong>: CRDB</li><li><strong>Account Name</strong>: Fursa Foundation</li><li><strong>Account Number</strong>: 0133717421200</li></ul><p> </p><hr /><p> </p><p><strong>Note</strong>: Please include <strong>&#8220;Donation&#8221;</strong> in the reference or description when making your transfer.</p><p>Your generosity is greatly appreciated and will directly impact the lives of women and girls in need. Thank you for your support!</p>					\n							<button type=\"button\" data-dismiss=\"premium-modal\">\n								Close							</button>\n			<svg xmlns=\"http://www.w3.org/2000/svg\" xmlns:xlink=\"http://www.w3.org/1999/xlink\" width=\"512\" height=\"512\" viewBox=\"0 0 512 512\" fill=\"none\"><mask id=\"mask0_118_58\" style=\"mask-type:alpha\" maskUnits=\"userSpaceOnUse\" x=\"0\" y=\"0\" width=\"512\" height=\"512\"><rect width=\"512\" height=\"512\" fill=\"url(#pattern0_118_58)\"></rect></mask><g mask=\"url(#mask0_118_58)\"><rect x=\"-16\" width=\"544\" height=\"544\" fill=\"#005CA9\"></rect></g><defs><pattern id=\"pattern0_118_58\" patternContentUnits=\"objectBoundingBox\" width=\"1\" height=\"1\"><use xlink:href=\"#image0_118_58\" transform=\"scale(0.00195312)\"></use></pattern><image id=\"image0_118_58\" width=\"512\" height=\"512\" xlink:href=\"data:image/png;base64,\"></image></defs></svg>			\n			<h5>Your Support Makes a Difference</h5>		\n		<p>Join our team to directly engage with communities, assist in workshops, and empower women through hands-on support.</p>		\n									<button data-toggle=\"premium-modal\" data-target=\"#premium-modal-07b28ed\" type=\"button\" data-text=\"Volunteer\">\n							Volunteer\n					</button>\n															<h3>\n									How to Volunteer								</h3>\n									<button type=\"button\" data-dismiss=\"premium-modal\">&times;</button>\n						<p>Join our mission by volunteering with Fursa Foundation! Help empower women and girls by contributing your time and skills through various initiatives.</p><p> </p><hr /><p> </p><p><strong>To Get Involved</strong>:</p><ul><li><strong>Email</strong>: Send your inquiry or volunteer interest to <strong><a rel=\"noopener\">info@fursafoundation.org</a></strong></li><li><strong>Subject Line</strong>: &#8220;Volunteer Inquiry&#8221;</li></ul><p> </p><p>We’ll get back to you with available opportunities and how you can make an impact!</p>					\n							<button type=\"button\" data-dismiss=\"premium-modal\">\n								Close							</button>\n			<svg xmlns=\"http://www.w3.org/2000/svg\" xmlns:xlink=\"http://www.w3.org/1999/xlink\" width=\"512\" height=\"512\" viewBox=\"0 0 512 512\" fill=\"none\"><mask id=\"mask0_118_57\" style=\"mask-type:alpha\" maskUnits=\"userSpaceOnUse\" x=\"0\" y=\"0\" width=\"512\" height=\"512\"><rect width=\"512\" height=\"512\" fill=\"url(#pattern0_118_57)\"></rect></mask><g mask=\"url(#mask0_118_57)\"><rect x=\"-32\" y=\"-32\" width=\"544\" height=\"544\" fill=\"#005CA9\"></rect></g><defs><pattern id=\"pattern0_118_57\" patternContentUnits=\"objectBoundingBox\" width=\"1\" height=\"1\"><use xlink:href=\"#image0_118_57\" transform=\"scale(0.00195312)\"></use></pattern><image id=\"image0_118_57\" width=\"512\" height=\"512\" xlink:href=\"data:image/png;base64,\"></image></defs></svg>			\n			<h5>Your Support Makes a Difference</h5>		\n		<p>Collaborate with us to broaden our impact and create lasting change for women and girls in need</p>		\n									<button data-toggle=\"premium-modal\" data-target=\"#premium-modal-f1a443c\" type=\"button\" data-text=\"Partner With Us\">\n							Partner With Us\n					</button>\n															<h3>\n									How to Partner with Us								</h3>\n									<button type=\"button\" data-dismiss=\"premium-modal\">&times;</button>\n						<p>Partnering with Fursa Foundation allows you to play a vital role in empowering women and girls across Tanzania. Together, we can create sustainable change and expand our reach to more communities in need.</p><p> </p><hr /><p> </p><p><strong>To Explore Partnership Opportunities</strong>:</p><ul><li><strong>Email</strong>: Send your partnership inquiries to <strong><a rel=\"noopener\">info@fursafoundation.org</a></strong></li><li><strong>Subject Line</strong>: &#8220;Partnership Inquiry&#8221;</li></ul><p> </p><p>Our team will respond with details on how we can collaborate to make a lasting impact. We look forward to working together!</p>					\n							<button type=\"button\" data-dismiss=\"premium-modal\">\n								Close							</button>\n			<h3>Have questions about how you can make a difference?</h3>		\n		<p>Whether you want to donate, volunteer, or partner with us, reach out to learn more about how you can be part of our mission to empower women and girls in Tanzania.</p>		\n			<a href=\"https://www.fursafoundation.org/contact-us/\">\n									Contact Us\n					</a>\n			<h2>What Our Beneficiaries Say</h2>		\n		<p>Hearing directly from those we’ve impacted is one of the most powerful ways to understand the difference we’re making.</p>		\n		<p>“Fursa Foundation’s reusable pads have made it possible for me to attend school without worrying. Now, I can focus on my education and participate in class with confidence. I no longer feel embarrassed or anxious during my period, and I know that I’m supported.”</p>		\n			<h6>Aisha, 15</h6>		\n													<img width=\"1080\" height=\"720\" src=\"https://www.fursafoundation.org/wp-content/uploads/2024/10/nudba-4.jpg\" alt=\"\" srcset=\"https://www.fursafoundation.org/wp-content/uploads/2024/10/nudba-4.jpg 1080w, https://www.fursafoundation.org/wp-content/uploads/2024/10/nudba-4-300x200.jpg 300w, https://www.fursafoundation.org/wp-content/uploads/2024/10/nudba-4-1024x683.jpg 1024w, https://www.fursafoundation.org/wp-content/uploads/2024/10/nudba-4-768x512.jpg 768w\" sizes=\"(max-width: 1080px) 100vw, 1080px\" />													\n			<figure class=\'gallery-item\'>\n				<a data-elementor-open-lightbox=\"yes\" data-elementor-lightbox-slideshow=\"97c8e55\" data-elementor-lightbox-title=\"fursafoundation-img-121\" data-e-action-hash=\"#elementor-action%3Aaction%3Dlightbox%26settings%3DeyJpZCI6MzA5LCJ1cmwiOiJodHRwczpcL1wvd3d3LmZ1cnNhZm91bmRhdGlvbi5vcmdcL3dwLWNvbnRlbnRcL3VwbG9hZHNcLzIwMjRcLzEwXC9mdXJzYWZvdW5kYXRpb24taW1nLTEyMS5qcGciLCJzbGlkZXNob3ciOiI5N2M4ZTU1In0%3D\" href=\'https://www.fursafoundation.org/wp-content/uploads/2024/10/fursafoundation-img-121.jpg\'><img width=\"560\" height=\"420\" src=\"https://www.fursafoundation.org/wp-content/uploads/2024/10/fursafoundation-img-121.jpg\" alt=\"\" decoding=\"async\" srcset=\"https://www.fursafoundation.org/wp-content/uploads/2024/10/fursafoundation-img-121.jpg 560w, https://www.fursafoundation.org/wp-content/uploads/2024/10/fursafoundation-img-121-300x225.jpg 300w\" sizes=\"(max-width: 560px) 100vw, 560px\" /></a>\n			</figure><figure class=\'gallery-item\'>\n				<a data-elementor-open-lightbox=\"yes\" data-elementor-lightbox-slideshow=\"97c8e55\" data-elementor-lightbox-title=\"fursafoundation-img-120\" data-e-action-hash=\"#elementor-action%3Aaction%3Dlightbox%26settings%3DeyJpZCI6MzA4LCJ1cmwiOiJodHRwczpcL1wvd3d3LmZ1cnNhZm91bmRhdGlvbi5vcmdcL3dwLWNvbnRlbnRcL3VwbG9hZHNcLzIwMjRcLzEwXC9mdXJzYWZvdW5kYXRpb24taW1nLTEyMC5qcGciLCJzbGlkZXNob3ciOiI5N2M4ZTU1In0%3D\" href=\'https://www.fursafoundation.org/wp-content/uploads/2024/10/fursafoundation-img-120.jpg\'><img width=\"560\" height=\"420\" src=\"https://www.fursafoundation.org/wp-content/uploads/2024/10/fursafoundation-img-120.jpg\" alt=\"\" decoding=\"async\" srcset=\"https://www.fursafoundation.org/wp-content/uploads/2024/10/fursafoundation-img-120.jpg 560w, https://www.fursafoundation.org/wp-content/uploads/2024/10/fursafoundation-img-120-300x225.jpg 300w\" sizes=\"(max-width: 560px) 100vw, 560px\" /></a>\n			</figure><figure class=\'gallery-item\'>\n				<a data-elementor-open-lightbox=\"yes\" data-elementor-lightbox-slideshow=\"97c8e55\" data-elementor-lightbox-title=\"IMG_6593_Original\" data-e-action-hash=\"